1	import * as THREE from 'three';
2	import type { App, Feature, FrameContext } from '../app';
3	import { copyPosition, getJointPose, type HandState } from '../input';
4	import { withoutOcclusion } from './occlusion';
5	
6	/** 人差し指が伸びているとみなす、まっすぐさ (付け根から先端の直線距離 / 指の長さ)。枠を作るとき / 保つとき */
7	const INDEX_STRAIGHT_FORM = 0.88;
8	const INDEX_STRAIGHT_HOLD = 0.75;
9	/**
10	 * 親指の先から人差し指の付け根側の節までの距離 (人差し指の長さに対する比)。
11	 * OPEN を超えたら開いている、FOLD を下回ったら倒したとみなす。
12	 */
13	const THUMB_OPEN = 0.6;
14	const THUMB_FOLD = 0.4;
15	/** 指が枠の内側を向いているとみなす、対角線の向きとの内積の下限 */
16	const INWARD_MIN = 0.25;
17	/**
18	 * 指が視線に対して横に寝ているとみなす、視線の向きとの内積 (絶対値) の上限。枠を作るとき / 保つとき。
19	 * 道具を使うときは人差し指が前 (視線の向き) を指すので、ここで枠と区別する。
20	 */
21	const ACROSS_VIEW_FORM = 0.5;
22	const ACROSS_VIEW_HOLD = 0.7;
23	/** 両手の人差し指どうし・親指どうしが逆を向いているとみなす、内積の上限。枠を作るとき / 保つとき */
24	const OPPOSED_FORM = -0.5;
25	const OPPOSED_HOLD = -0.2;
26	/** 枠の形をこの秒数だけ保つと、枠が出る。手を動かす途中で一瞬その形になっただけでは出さない。 */
27	const FORM_DELAY = 0.35;
28	/**
29	 * 枠を、両手の角が作る四角形より各辺この長さだけ内側に縮める (m)。指が写真に写り込まないようにする。
30	 * 指の太さに加えて、カメラが目とは違う位置から手を見ているぶんのずれも見込んでいる。
31	 */
32	const FINGER_INSET = 0.03;
33	/** 枠の一辺の長さの範囲 (m) */
34	const MIN_SIDE = 0.04;
35	const MAX_SIDE = 0.7;
36	/** 枠ができてから、撮れるようになるまでの秒数。枠を作る動きの途中で撮れてしまわないようにする。 */
37	const ARM_DELAY = 0.3;
38	/** 次に撮れるようになるまでの秒数 */
39	const COOLDOWN = 0.8;
40	/** 写真の長辺のピクセル数 */
41	const CAPTURE_SIZE = 1280;
42	/** 空間に残す写真の枚数。超えたら古いものから消す (保存用の一覧には残る)。 */
43	const MAX_WORLD_PHOTOS = 8;
44	/** 空間に残す写真の、枠に対する大きさ */
45	const PHOTO_SCALE = 0.6;
46	const BORDER = 0.004;
47	const FLASH_DURATION = 0.25;
48	/**
49	 * パススルーカメラの水平画角 (度)。ブラウザからはカメラの内部パラメータが取れないので、仮の値。
50	 * 写真の中の現実の景色が、枠から見えた範囲より広く写るなら大きく、狭く写るなら小さくする。
51	 */
52	const CAMERA_FOV_HORIZONTAL = 73;
53	/**
54	 * パススルーカメラが、頭の正面に対して下を向いている角度 (度)。これも仮の値。
55	 * 写真の中の現実の景色が、枠から見えた範囲より下にずれるなら大きく、上にずれるなら小さくする。
56	 */
57	const CAMERA_PITCH_DOWN = 12;
58	/** 頭の向き → カメラの向き の回転 */
59	const CAMERA_TILT = new THREE.Quaternion().setFromAxisAngle(
60	  new THREE.Vector3(1, 0, 0),
61	  -THREE.MathUtils.degToRad(CAMERA_PITCH_DOWN),
62	);
63	/** カメラの映像がない所の色 (sRGB) */
64	const BACKDROP = new THREE.Color(0x10141c);
65	
66	const FULLSCREEN_VERTEX = /* glsl */ `
67	varying vec2 vNdc;
68	void main() {
69	  vNdc = position.xy;
70	  gl_Position = vec4(position.xy, 0.0, 1.0);
71	}`;
72	
73	/**
74	 * 仮想物体の描画結果 (リニア、アルファ乗算済み) を、カメラの映像の上に重ねて sRGB で出力する。
75	 * カメラの映像は、枠の中の各画素が向いている方向を、カメラから見た方向に直して引く。
76	 * 景色は十分遠くにあるものとして、頭とカメラの位置の差は無視している。
77	 */
78	const COMPOSITE_FRAGMENT = /* glsl */ `
79	uniform sampler2D virtualMap;
80	uniform sampler2D videoMap;
81	uniform bool hasVideo;
82	uniform mat3 toVideo;
83	uniform vec2 captureTan;
84	uniform vec2 videoTan;
85	uniform vec3 backdrop;
86	varying vec2 vNdc;
87	
88	vec3 toLinear(vec3 c) {
89	  return mix(c / 12.92, pow((c + 0.055) / 1.055, vec3(2.4)), step(0.04045, c));
90	}
91	
92	vec3 toSrgb(vec3 c) {
93	  c = clamp(c, 0.0, 1.0);
94	  return mix(c * 12.92, 1.055 * pow(c, vec3(1.0 / 2.4)) - 0.055, step(0.0031308, c));
95	}
96	
97	void main() {
98	  vec3 real = toLinear(backdrop);
99	  if (hasVideo) {
100	    vec3 direction = toVideo * vec3(vNdc * captureTan, -1.0);
101	    vec2 uv = direction.xy / (max(-direction.z, 1e-4) * videoTan) * 0.5 + 0.5;
102	    if (direction.z < 0.0 && uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) {
103	      real = toLinear(texture2D(videoMap, uv).rgb);
104	    }
105	  }
106	  vec4 overlay = texture2D(virtualMap, vNdc * 0.5 + 0.5);
107	  gl_FragColor = vec4(toSrgb(overlay.rgb + real * (1.0 - overlay.a)), 1.0);
108	}`;
109	
110	/** 枠を作る片手の形 */
111	interface FrameHand {
112	  /** 親指と人差し指の付け根の間。枠の角になる。 */
113	  corner: THREE.Vector3;
114	  indexDirection: THREE.Vector3;
115	  thumbDirection: THREE.Vector3;
116	  indexStraightness: number;
117	  thumbGap: number;
118	  /** 親指を倒している (THUMB_OPEN / THUMB_FOLD の間では前の状態を保つ) */
119	  folded: boolean;
120	}
121	
122	export interface Photo {
123	  url: string;
124	  name: string;
125	}
126	
127	export interface CameraInfo {
128	  /** 映像を再生している要素。ページに置けば、何が映っているか確かめられる。 */
129	  video: HTMLVideoElement;
130	  cameras: { deviceId: string; label: string }[];
131	  /** 使用中のカメラ */
132	  deviceId: string;
133	}
134	
135	const _a = new THREE.Vector3();
136	const _b = new THREE.Vector3();
137	const _c = new THREE.Vector3();
138	const _d = new THREE.Vector3();
139	const _thumbBase = new THREE.Vector3();
140	const _thumbTip = new THREE.Vector3();
141	const _indexDistal = new THREE.Vector3();
142	const _indexTip = new THREE.Vector3();
143	const _diagonal = new THREE.Vector3();
144	const _right = new THREE.Vector3();
145	const _up = new THREE.Vector3();
146	const _normal = new THREE.Vector3();
147	const _matrix = new THREE.Matrix4();
148	const _quaternion = new THREE.Quaternion();
149	const _clearColor = new THREE.Color();
150	
151	function newFrameHand(): FrameHand {
152	  return {
153	    corner: new THREE.Vector3(),
154	    indexDirection: new THREE.Vector3(),
155	    thumbDirection: new THREE.Vector3(),
156	    indexStraightness: 0,
157	    thumbGap: 0,
158	    folded: false,
159	  };
160	}
161	
162	/** 点 p から線分 ab までの距離 */
163	function distanceToSegment(p: THREE.Vector3, a: THREE.Vector3, b: THREE.Vector3): number {
164	  _d.subVectors(b, a);
165	  const t = THREE.MathUtils.clamp(_c.subVectors(p, a).dot(_d) / Math.max(_d.lengthSq(), 1e-8), 0, 1);
166	  return _c.copy(a).addScaledVector(_d, t).distanceTo(p);
167	}
