169	/**
170	 * 両手の親指と人差し指で四角を作ると枠が出て、どちらかの親指を倒すと、枠の中に見えている景色を写真に撮る。
171	 *
172	 * 手の形は hand-tracking の関節の位置から判定する。片手ごとに「人差し指が伸び、親指が開いている (L 字)」
173	 * ことを調べ、両手の L 字の角を対角とする四角形を、頭から見て正面を向く向きに作る。
174	 *
175	 * 写真は、頭の位置から枠を通して見た範囲を、仮想物体だけレンダーターゲットに描いて作る。
176	 * WebXR のフレームバッファにはパススルー映像が入っていない (合成は OS 側で行われる) ので、
177	 * 現実の景色は getUserMedia で取ったパススルーカメラの映像から、同じ範囲を切り出して下に敷く。
178	 * カメラを許可していない場合は、仮想物体だけの写真になる。
179	 */
180	export class HandFrame implements Feature {
181	  readonly name = 'handFrame';
182	  enabled = true;
183	  /** 撮った写真。セッションを終えたあと、ページから保存できる。 */
184	  readonly photos: Photo[] = [];
185	  /** 撮った瞬間の通知 (効果音など) */
186	  onCapture: ((position: THREE.Vector3) => void) | null = null;
187	  /** 写真が画像ファイルになったときの通知 */
188	  onPhoto: ((photo: Photo) => void) | null = null;
189	
190	  private readonly left = newFrameHand();
191	  private readonly right = newFrameHand();
192	  private active = false;
193	  /** 枠の形になり始めた時刻。なっていなければ負 */
194	  private formingSince = -1;
195	  private activeSince = 0;
196	  private lastCapture = -Infinity;
197	  private flashUntil = 0;
198	
199	  /** 枠の中心・向き・大きさ */
200	  private readonly center = new THREE.Vector3();
201	  private readonly quaternion = new THREE.Quaternion();
202	  private width = 0;
203	  private height = 0;
204	
205	  private readonly frame = new THREE.Group();
206	  private readonly bars: THREE.Mesh[] = [];
207	  private readonly flash: THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial>;
208	  private readonly worldPhotos: THREE.Group[] = [];
209	
210	  private readonly captureCamera = new THREE.PerspectiveCamera();
211	  // 仮想物体はリニアで描かれるので、暗部が潰れないよう 8 ビットより精度のある形式で受ける。
212	  private readonly virtualTarget = new THREE.WebGLRenderTarget(1, 1, {
213	    type: THREE.HalfFloatType,
214	    stencilBuffer: true,
215	  });
216	  private readonly outputTarget = new THREE.WebGLRenderTarget(1, 1, { depthBuffer: false });
217	  private readonly compositeMaterial = new THREE.ShaderMaterial({
218	    vertexShader: FULLSCREEN_VERTEX,
219	    fragmentShader: COMPOSITE_FRAGMENT,
220	    depthTest: false,
221	    depthWrite: false,
222	    uniforms: {
223	      virtualMap: { value: this.virtualTarget.texture },
224	      videoMap: { value: null as THREE.Texture | null },
225	      hasVideo: { value: false },
226	      toVideo: { value: new THREE.Matrix3() },
227	      captureTan: { value: new THREE.Vector2(1, 1) },
228	      videoTan: { value: new THREE.Vector2(1, 1) },
229	      backdrop: { value: new THREE.Vector3(BACKDROP.r, BACKDROP.g, BACKDROP.b) },
230	    },
231	  });
232	  private readonly compositeScene = new THREE.Scene();
233	
234	  private video: HTMLVideoElement | null = null;
235	  private videoTexture: THREE.VideoTexture | null = null;
236	  private time = 0;
237	  private lastVideoTime = 0;
238	  private videoAdvancedAt = -Infinity;
239	
240	  constructor(private readonly app: App) {
241	    // Color は内部でリニアに直されるので、シェーダーに渡す sRGB の値を取り直す。
242	    BACKDROP.getRGB(_clearColor, THREE.SRGBColorSpace);
243	    this.compositeMaterial.uniforms.backdrop.value.set(_clearColor.r, _clearColor.g, _clearColor.b);
244	    const quad = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), this.compositeMaterial);
245	    quad.frustumCulled = false;
246	    this.compositeScene.add(quad);
247	
248	    // 枠は手に重なる位置にあるので、深度を無視して常に見せる。
249	    const barMaterial = new THREE.MeshBasicMaterial({ color: 0xffffff, depthTest: false, side: THREE.DoubleSide });
250	    const barGeometry = new THREE.PlaneGeometry(1, 1);
251	    for (let i = 0; i < 4; i++) {
252	      const bar = new THREE.Mesh(barGeometry, barMaterial);
253	      bar.renderOrder = 90;
254	      this.bars.push(bar);
255	      this.frame.add(bar);
256	    }
257	    this.flash = new THREE.Mesh(
258	      barGeometry,
259	      new THREE.MeshBasicMaterial({
260	        color: 0xffffff,
261	        transparent: true,
262	        opacity: 0,
263	        depthTest: false,
264	        side: THREE.DoubleSide,
265	      }),
266	    );
267	    this.flash.renderOrder = 89;
268	    this.flash.visible = false;
269	    this.frame.add(this.flash);
270	    this.frame.visible = false;
271	    app.scene.add(this.frame);
272	
273	    app.menu.addToggle(
274	      '手で撮影',
275	      () => this.enabled,
276	      (value) => (this.enabled = value),
277	    );
278	    // 枠を作っている間は、親指の動きがつまみと判定されても道具を発動させない。
279	    app.tools.addInterceptor(() => this.active);
280	    app.onClear(() => this.clearWorldPhotos());
281	  }
282	
283	  /** カメラの映像が取れていて、写真に現実の景色が入るか */
284	  get cameraReady(): boolean {
285	    const video = this.video;
286	    return video !== null && video.readyState >= 2 && video.videoWidth > 0;
287	  }
288	
289	  /** カメラの映像が、いまも更新され続けているか。MR セッション中に止まる環境を見分けるためのもの。 */
290	  get cameraLive(): boolean {
291	    return this.cameraReady && this.time - this.videoAdvancedAt < 1;
292	  }
293	
294	  /**
295	   * カメラの映像を取り始める。許可のダイアログが出るので、MR を始める前に、
296	   * ユーザー操作 (ボタンのクリック) の中で呼ぶ。
297	   * deviceId を省くと、背面 (パススルー) のカメラらしいものを選ぶ。
298	   */
299	  async startCamera(deviceId?: string): Promise<CameraInfo | null> {
300	    const media = navigator.mediaDevices;
301	    if (!media?.getUserMedia) return null;
302	    const size = { width: { ideal: 1280 }, height: { ideal: 960 } };
303	    this.stopCamera();
304	    let stream = await media.getUserMedia({
305	      video: deviceId ? { deviceId: { exact: deviceId }, ...size } : { facingMode: 'environment', ...size },
306	    });
307	    // カメラの名前は、許可が下りたあとでないと読めない。
308	    const cameras = (await media.enumerateDevices())
309	      .filter((device) => device.kind === 'videoinput')
310	      .map((device, i) => ({ deviceId: device.deviceId, label: device.label || `カメラ ${i + 1}` }));
311	    let current = stream.getVideoTracks()[0]?.getSettings().deviceId ?? '';
312	    if (!deviceId) {
313	      // Quest のブラウザには、アバターを映す仮想カメラもある。facingMode の指定が効かずに
314	      // そちらが選ばれた場合に備えて、名前からも背面のカメラを探す。
315	      // Quest 3 では "camera 1, facing back" と "camera 2, facing back" の 2 つがあり、
316	      // 画角と傾きの値は camera 2 で合わせてあるので、そちらを優先する。
317	      const back =
318	        cameras.find((camera) => /camera 2\b.*back/i.test(camera.label)) ??
319	        cameras.find((camera) => /back|rear|environment|passthrough/i.test(camera.label));
320	      if (back && back.deviceId !== current) {
321	        for (const track of stream.getTracks()) track.stop();
322	        stream = await media.getUserMedia({ video: { deviceId: { exact: back.deviceId }, ...size } });
323	        current = back.deviceId;
324	      }
325	    }
326	
327	    const video = document.createElement('video');
328	    video.srcObject = stream;
329	    video.muted = true;
330	    video.playsInline = true;
331	    await video.play();
332	    const texture = new THREE.VideoTexture(video);
333	    // 色の変換は合成のシェーダーで自前で行うので、映像の値をそのまま読む。
334	    texture.colorSpace = THREE.NoColorSpace;
335	    this.video = video;
336	    this.videoTexture = texture;
337	    this.compositeMaterial.uniforms.videoMap.value = texture;
338	    return { video, cameras, deviceId: current };
339	  }
