352	    this.time = time;
353	    const videoTime = this.video?.currentTime ?? 0;
354	    if (videoTime !== this.lastVideoTime) {
355	      this.lastVideoTime = videoTime;
356	      this.videoAdvancedAt = time;
357	    }
