372	  update(ctx: FrameContext): void {
373	    const wasActive = this.active;
374	    const leftFolded = this.left.folded;
375	    const rightFolded = this.right.folded;
376	    const input = this.app.input;
377	    const readable =
378	      this.enabled && this.readHand(ctx, input.left, this.left) && this.readHand(ctx, input.right, this.right);
379	    const shaped = readable && this.checkShape(ctx.headPosition);
380	    if (!shaped) {
381	      this.active = false;
382	      this.formingSince = -1;
383	      this.left.folded = false;
384	      this.right.folded = false;
385	    } else if (!this.active) {
386	      if (this.formingSince < 0) this.formingSince = ctx.time;
387	      if (ctx.time - this.formingSince >= FORM_DELAY) {
388	        this.active = true;
389	        this.activeSince = ctx.time;
390	      }
391	    }
392	    this.trackVideo(ctx.time);
393	
394	    if (this.active) {
395	      // 親指を倒すと手の形が変わって枠の角がずれるので、倒している間は枠を動かさない。
396	      if (!this.left.folded && !this.right.folded) this.updateRect(ctx.headPosition, ctx.headQuaternion);
397	      const pressed = (this.left.folded && !leftFolded) || (this.right.folded && !rightFolded);
398	      if (
399	        pressed &&
400	        wasActive &&
401	        ctx.time - this.activeSince > ARM_DELAY &&
402	        ctx.time - this.lastCapture > COOLDOWN
403	      ) {
404	        this.lastCapture = ctx.time;
405	        this.flashUntil = ctx.time + FLASH_DURATION;
406	        this.capture(ctx);
407	        input.left.pulse(0.8, 40);
408	        input.right.pulse(0.8, 40);
409	        this.onCapture?.(this.center);
410	      }
411	    }
412	    this.updateFrame(ctx.time);
413	  }
