415	  /** 関節の位置から、片手の形を読む。素手でない、または関節が取れなければ false。 */
416	  private readHand(ctx: FrameContext, hand: HandState, out: FrameHand): boolean {
417	    const xrHand = hand.source?.hand;
418	    if (!hand.tracked || !xrHand) return false;
419	    const { frame, refSpace } = ctx;
420	    const thumbBase = getJointPose(frame, xrHand, 'thumb-phalanx-proximal', refSpace);
421	    const thumbTip = getJointPose(frame, xrHand, 'thumb-tip', refSpace);
422	    const proximal = getJointPose(frame, xrHand, 'index-finger-phalanx-proximal', refSpace);
423	    const intermediate = getJointPose(frame, xrHand, 'index-finger-phalanx-intermediate', refSpace);
424	    const distal = getJointPose(frame, xrHand, 'index-finger-phalanx-distal', refSpace);
425	    const tip = getJointPose(frame, xrHand, 'index-finger-tip', refSpace);
426	    if (!thumbBase || !thumbTip || !proximal || !intermediate || !distal || !tip) return false;
427	
428	    copyPosition(_thumbBase, thumbBase.transform.position);
429	    copyPosition(_thumbTip, thumbTip.transform.position);
430	    const indexBase = copyPosition(_a, proximal.transform.position);
431	    const indexMiddle = copyPosition(_b, intermediate.transform.position);
432	    const indexDistal = copyPosition(_indexDistal, distal.transform.position);
433	    const indexTip = copyPosition(_indexTip, tip.transform.position);
434	    // 手の大きさによらず判定できるよう、人差し指の長さを基準にする。
435	    const indexLength =
436	      indexBase.distanceTo(indexMiddle) + indexMiddle.distanceTo(indexDistal) + indexDistal.distanceTo(indexTip);
437	    if (indexLength < 1e-4) return false;
438	    out.indexStraightness = indexBase.distanceTo(indexTip) / indexLength;
439	    out.thumbGap = distanceToSegment(_thumbTip, indexBase, indexMiddle) / indexLength;
440	    if (out.thumbGap > THUMB_OPEN) out.folded = false;
441	    else if (out.thumbGap < THUMB_FOLD) out.folded = true;
442	
443	    out.corner.addVectors(_thumbBase, indexBase).multiplyScalar(0.5);
444	    out.indexDirection.subVectors(indexTip, indexBase).normalize();
445	    out.thumbDirection.subVectors(_thumbTip, _thumbBase).normalize();
446	    return true;
447	  }
