496	  /** 両手の角を対角とする四角形を、頭のほうを向く平面の上に作る。 */
497	  private updateRect(head: THREE.Vector3, headQuaternion: THREE.Quaternion): void {
498	    this.center.addVectors(this.left.corner, this.right.corner).multiplyScalar(0.5);
499	    _normal.subVectors(head, this.center).normalize();
500	    // 写真が傾かないよう、上辺は水平にする。真上や真下を向いているときだけ、頭の向きに合わせる。
501	    if (Math.abs(_normal.y) < 0.95) _up.set(0, 1, 0);
502	    else _up.set(0, 1, 0).applyQuaternion(headQuaternion);
503	    _up.addScaledVector(_normal, -_up.dot(_normal)).normalize();
504	    _right.crossVectors(_up, _normal);
505	    this.quaternion.setFromRotationMatrix(_matrix.makeBasis(_right, _up, _normal));
506	    _diagonal.subVectors(this.right.corner, this.left.corner);
507	    this.width = THREE.MathUtils.clamp(Math.abs(_diagonal.dot(_right)) - FINGER_INSET * 2, MIN_SIDE, MAX_SIDE);
508	    this.height = THREE.MathUtils.clamp(Math.abs(_diagonal.dot(_up)) - FINGER_INSET * 2, MIN_SIDE, MAX_SIDE);
509	  }
510	
511	  private updateFrame(time: number): void {
512	    const flashing = time < this.flashUntil;
513	    this.frame.visible = this.active || flashing;
514	    if (!this.frame.visible) return;
515	    const { width, height } = this;
516	    this.frame.position.copy(this.center);
517	    this.frame.quaternion.copy(this.quaternion);
518	    const [top, bottom, left, right] = this.bars;
519	    top.position.set(0, height / 2, 0);
520	    bottom.position.set(0, -height / 2, 0);
521	    top.scale.set(width + BORDER, BORDER, 1);
522	    bottom.scale.copy(top.scale);
523	    left.position.set(-width / 2, 0, 0);
524	    right.position.set(width / 2, 0, 0);
525	    left.scale.set(BORDER, height + BORDER, 1);
526	    right.scale.copy(left.scale);
527	    this.flash.visible = flashing;
528	    this.flash.scale.set(width, height, 1);
529	    this.flash.material.opacity = flashing ? (0.7 * (this.flashUntil - time)) / FLASH_DURATION : 0;
530	  }
531	
532	  /** 頭の位置から枠を通して見た範囲を、写真にする。 */
533	  private capture(ctx: FrameContext): void {
534	    const { renderer, scene } = this.app;
535	    const { width, height } = this;
536	    const distance = Math.max(ctx.headPosition.distanceTo(this.center), 0.05);
537	    const scale = CAPTURE_SIZE / Math.max(width, height);
538	    const pixelWidth = Math.max(Math.round(width * scale), 2);
539	    const pixelHeight = Math.max(Math.round(height * scale), 2);
540	
541	    // 枠は頭の正面を向けて作ってあるので、視線の軸に対して左右・上下が対称な、普通の透視投影になる。
542	    const camera = this.captureCamera;
543	    camera.position.copy(ctx.headPosition);
544	    camera.quaternion.copy(this.quaternion);
545	    camera.fov = THREE.MathUtils.radToDeg(2 * Math.atan(height / 2 / distance));
546	    camera.aspect = width / height;
547	    // 枠より手前にあるもの (手のカーソルなど) は写さない。
548	    camera.near = distance;
549	    camera.far = 50;
550	    camera.updateProjectionMatrix();
551	
552	    const uniforms = this.compositeMaterial.uniforms;
553	    uniforms.captureTan.value.set(width / 2 / distance, height / 2 / distance);
554	    const video = this.video;
555	    const hasVideo = this.cameraReady && video !== null && this.videoTexture !== null;
556	    uniforms.hasVideo.value = hasVideo;
557	    if (hasVideo) {
558	      // XR セッション中は映像の更新通知が来ないことがあるので、撮る直前に必ず取り込み直す。
559	      this.videoTexture!.needsUpdate = true;
560	      const tanHorizontal = Math.tan(THREE.MathUtils.degToRad(CAMERA_FOV_HORIZONTAL / 2));
561	      uniforms.videoTan.value.set(tanHorizontal, (tanHorizontal * video.videoHeight) / video.videoWidth);
562	      // カメラは頭に固定されているものとして、枠の向き → カメラの向き の回転を求める。
563	      _quaternion.copy(ctx.headQuaternion).multiply(CAMERA_TILT).invert().multiply(this.quaternion);
564	      uniforms.toVideo.value.setFromMatrix4(_matrix.makeRotationFromQuaternion(_quaternion));
565	    }
566	
567	    this.virtualTarget.setSize(pixelWidth, pixelHeight);
568	    this.outputTarget.setSize(pixelWidth, pixelHeight);
569	    const pixels = new Uint8Array(pixelWidth * pixelHeight * 4);
570	
571	    // XR セッション中の renderer は、XR のカメラで XR のフレームバッファへ描く。
572	    // その設定を一時的に外して、自前のカメラでレンダーターゲットへ描く。
573	    const previousTarget = renderer.getRenderTarget();
574	    const previousXr = renderer.xr.enabled;
575	    const previousAlpha = renderer.getClearAlpha();
576	    renderer.getClearColor(_clearColor);
577	    const frameVisible = this.frame.visible;
578	    this.frame.visible = false;
579	    // 前に撮った写真は写さない。同じ場所で続けて撮ると、前の写真が景色を覆ってしまう。
580	    for (const photo of this.worldPhotos) photo.visible = false;
581	    try {
582	      renderer.xr.enabled = false;
583	      renderer.setClearColor(0x000000, 0);
584	      renderer.setRenderTarget(this.virtualTarget);
585	      withoutOcclusion(() => renderer.render(scene, camera));
586	      renderer.setRenderTarget(this.outputTarget);
587	      renderer.render(this.compositeScene, camera);
588	      renderer.readRenderTargetPixels(this.outputTarget, 0, 0, pixelWidth, pixelHeight, pixels);
589	    } finally {
590	      renderer.setRenderTarget(previousTarget);
591	      renderer.setClearColor(_clearColor, previousAlpha);
592	      renderer.xr.enabled = previousXr;
593	      this.frame.visible = frameVisible;
594	      for (const photo of this.worldPhotos) photo.visible = true;
595	    }
596	
597	    // 読み出した画素は下の行から並んでいるので、上下を入れ替えてキャンバスに置く。
598	    const canvas = document.createElement('canvas');
599	    canvas.width = pixelWidth;
600	    canvas.height = pixelHeight;
601	    const context = canvas.getContext('2d');
602	    if (!context) return;
603	    const image = context.createImageData(pixelWidth, pixelHeight);
604	    const rowBytes = pixelWidth * 4;
605	    for (let y = 0; y < pixelHeight; y++) {
606	      const source = (pixelHeight - 1 - y) * rowBytes;
607	      image.data.set(pixels.subarray(source, source + rowBytes), y * rowBytes);
608	    }
609	    context.putImageData(image, 0, 0);
610	
611	    this.addWorldPhoto(canvas);
612	    const name = `mr-playroom-${new Date().toISOString().replace(/[:.]/g, '-')}.jpg`;
613	    canvas.toBlob(
614	      (blob) => {
615	        if (!blob) return;
616	        const photo: Photo = { url: URL.createObjectURL(blob), name };
617	        this.photos.push(photo);
618	        this.onPhoto?.(photo);
619	      },
620	      'image/jpeg',
621	      0.92,
622	    );
623	  }
624	
625	  /** 撮った写真を、撮った場所に浮かべて残す。 */
626	  private addWorldPhoto(canvas: HTMLCanvasElement): void {
627	    const texture = new THREE.CanvasTexture(canvas);
628	    texture.colorSpace = THREE.SRGBColorSpace;
629	    const photo = new THREE.Group();
630	    const picture = new THREE.Mesh(
631	      new THREE.PlaneGeometry(this.width, this.height),
632	      new THREE.MeshBasicMaterial({ map: texture, side: THREE.DoubleSide }),
633	    );
634	    const mount = new THREE.Mesh(
635	      new THREE.PlaneGeometry(this.width + 0.012, this.height + 0.012),
636	      new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide }),
637	    );
638	    mount.position.z = -0.001;
639	    photo.add(mount, picture);
640	    // 枠の位置にそのまま残すと次に撮る景色を塞ぐので、縮めて枠の下に置く。
641	    photo.scale.setScalar(PHOTO_SCALE);
642	    photo.quaternion.copy(this.quaternion);
643	    _up.set(0, 1, 0).applyQuaternion(this.quaternion);
644	    photo.position.copy(this.center).addScaledVector(_up, -(this.height * (1 + PHOTO_SCALE)) / 2 - 0.03);
645	    this.app.scene.add(photo);
646	    this.worldPhotos.push(photo);
647	    while (this.worldPhotos.length > MAX_WORLD_PHOTOS) this.removeWorldPhoto(this.worldPhotos.shift()!);
648	  }
649	
650	  private clearWorldPhotos(): void {
651	    for (const photo of this.worldPhotos) this.removeWorldPhoto(photo);
652	    this.worldPhotos.length = 0;
653	  }
654	
655	  private removeWorldPhoto(photo: THREE.Group): void {
656	    this.app.scene.remove(photo);
657	    for (const child of photo.children) {
658	      const mesh = child as THREE.Mesh<THREE.PlaneGeometry, THREE.MeshBasicMaterial>;
659	      mesh.geometry.dispose();
660	      mesh.material.map?.dispose();
661	      mesh.material.dispose();
662	    }
663	  }
664	}
