1	import * as THREE from 'three';
2	import type { App, Feature } from '../app';
3	import type { HandState } from '../input';
4	
5	interface Stroke {
6	  points: THREE.Vector3[];
7	  mesh: THREE.Mesh<THREE.BufferGeometry, THREE.MeshStandardMaterial>;
8	}
9	
10	const RADIUS = 0.006;
11	/** これ以上動いたら点を足す (m) */
12	const MIN_STEP = 0.008;
13	/** 1 本の線の点数の上限。超えたら新しい線に切り替える (点が増えるほど作り直しが重くなるため)。 */
14	const MAX_POINTS = 400;
15	const COLORS = [0xff6b6b, 0xffd166, 0x6fe09a, 0x4f8cff, 0xc58cff, 0xffffff];
16	
17	/**
18	 * 空中に線を描く。素手ではつまんだ指先、コントローラーではトリガーを引いた先端が筆になる。
19	 * 線は空間に残るので、歩き回って別の角度から見られる。
20	 */
21	export class Drawing implements Feature {
22	  readonly name = 'drawing';
23	  private readonly strokes: Stroke[] = [];
24	  private readonly active = new Map<HandState, Stroke>();
25	  private nextColor = 0;
26	
27	  constructor(private readonly app: App) {
28	    app.tools.register({
29	      id: 'draw',
30	      label: 'お絵描き',
31	      hint: 'つまむ/トリガーを引いたまま動かして描く',
32	      onSelectStart: (hand) => this.begin(hand),
33	      onSelectEnd: (hand) => this.finish(hand),
34	    });
35	    app.onClear(() => this.clear());
36	  }
37	
38	  get count(): number {
39	    return this.strokes.length;
40	  }
41	
42	  end(): void {
43	    this.clear();
44	  }
45	
46	  clear(): void {
47	    for (const stroke of this.strokes) this.dispose(stroke);
48	    this.strokes.length = 0;
49	    this.active.clear();
50	  }
51	
52	  update(): void {
53	    for (const [hand, stroke] of this.active) {
54	      if (!hand.tracked) continue;
55	      const point = penPosition(hand);
56	      const last = stroke.points[stroke.points.length - 1];
57	      if (point.distanceTo(last) < MIN_STEP) continue;
58	      stroke.points.push(point.clone());
59	      rebuild(stroke);
60	      if (stroke.points.length >= MAX_POINTS) {
61	        // 続きは新しい線で描く。同じ色・同じ点から始めるので、見た目はつながる。
62	        const next = this.createStroke(point, stroke.mesh.material.color.getHex());
63	        this.active.set(hand, next);
64	      }
65	    }
66	  }
67	
68	  private begin(hand: HandState): void {
69	    if (!hand.tracked) return;
70	    const color = COLORS[this.nextColor];
71	    this.nextColor = (this.nextColor + 1) % COLORS.length;
72	    this.active.set(hand, this.createStroke(penPosition(hand), color));
73	  }
74	
75	  private finish(hand: HandState): void {
76	    const stroke = this.active.get(hand);
77	    this.active.delete(hand);
78	    // 動かさずに離した場合は、線にならないので捨てる。
79	    if (stroke && stroke.points.length < 2) {
80	      this.dispose(stroke);
81	      this.strokes.splice(this.strokes.indexOf(stroke), 1);
82	    }
83	  }
84	
85	  private createStroke(start: THREE.Vector3, color: number): Stroke {
86	    const material = new THREE.MeshStandardMaterial({
87	      color,
88	      emissive: color,
89	      emissiveIntensity: 0.35,
90	      roughness: 0.5,
91	    });
92	    const mesh = new THREE.Mesh(new THREE.BufferGeometry(), material);
93	    mesh.castShadow = true;
94	    // 線は長く伸びるので、作り直すたびに境界を計算するより、常に描画対象にする。
95	    mesh.frustumCulled = false;
96	    this.app.scene.add(mesh);
97	    const stroke: Stroke = { points: [start.clone()], mesh };
98	    this.strokes.push(stroke);
99	    return stroke;
100	  }
101	
102	  private dispose(stroke: Stroke): void {
103	    this.app.scene.remove(stroke.mesh);
104	    stroke.mesh.geometry.dispose();
105	    stroke.mesh.material.dispose();
106	  }
107	}
108	
109	function penPosition(hand: HandState): THREE.Vector3 {
110	  return hand.isHand ? hand.grabPosition : hand.tipPosition;
111	}
112	
113	/** 点列をなめらかな曲線でつなぎ、チューブ状のメッシュにする。 */
114	function rebuild(stroke: Stroke): void {
115	  stroke.mesh.geometry.dispose();
116	  stroke.mesh.geometry = new THREE.TubeGeometry(
117	    new THREE.CatmullRomCurve3(stroke.points),
118	    stroke.points.length * 2,
119	    RADIUS,
120	    6,
121	    false,
122	  );
123	}
