128	    this.placed.length = 0;
129	    this.unrestored = [];
130	    this.save();
131	  }
132	
133	  private save(): void {
134	    store([...this.unrestored, ...this.placed.flatMap((p) => (p.uuid ? [{ uuid: p.uuid, kind: p.kind }] : []))]);
135	  }
136	
137	  update(ctx: FrameContext): void {
138	    for (const hand of this.pending.splice(0)) this.place(hand, ctx);
139	
140	    for (const placed of this.placed) {
141	      if (!placed.anchor) continue;
142	      // trackedAnchors は、いま追跡できているアンカーの集合。作った直後はまだ入っていない。
143	      const pose = ctx.frame.trackedAnchors?.has(placed.anchor)
144	        ? ctx.frame.getPose(placed.anchor.anchorSpace, ctx.refSpace)
145	        : null;
146	      if (!pose) continue;
147	      placed.object.visible = true;
148	      copyPosition(placed.object.position, pose.transform.position);
149	      copyQuaternion(placed.object.quaternion, pose.transform.orientation);
150	    }
151	  }
152	
153	  private place(hand: HandState, ctx: FrameContext): void {
154	    const hit = this.hitTest.getHit(hand);
155	    if (!hit) return;
156	    let kind: Kind = 'picture';
157	    if (isHorizontal(hit.normal)) {
158	      kind = FLOOR_KINDS[this.nextKind];
159	      this.nextKind = (this.nextKind + 1) % FLOOR_KINDS.length;
160	    }
161	    const placed: Placed = { kind, object: build(kind), anchor: null, uuid: null };
162	    placed.object.position.copy(hit.position);
163	    orientOnSurface(hit.position, hit.normal, ctx.headPosition, placed.object.quaternion);
164	    this.add(placed);
165	    hand.pulse(0.7, 40);
166	    this.onPlaced?.(hit.position);
167	
168	    // XRHitTestResult.createAnchor() でも作れるが、物の向きをこちらで決めたいので
169	    // 姿勢を指定できる frame.createAnchor() を使う。アンカーの姿勢 = 物の姿勢になる。
170	    _quaternion.copy(placed.object.quaternion);
171	    const transform = new XRRigidTransform(
172	      { x: hit.position.x, y: hit.position.y, z: hit.position.z },
173	      { x: _quaternion.x, y: _quaternion.y, z: _quaternion.z, w: _quaternion.w },
174	    );
175	    ctx.frame
176	      .createAnchor?.(transform, ctx.refSpace)
177	      ?.then((anchor) => {
178	        if (!this.placed.includes(placed)) {
179	          anchor.delete();
180	          return;
181	        }
182	        placed.anchor = anchor;
183	        return this.persist(placed, anchor);
184	      })
185	      .catch((error: unknown) => {
186	        console.warn('[placement] アンカーを作れませんでした。置いた時の座標のまま表示します', error);
187	      });
188	  }
189	
190	  private async persist(placed: Placed, anchor: XRAnchor): Promise<void> {
191	    if (!anchor.requestPersistentHandle) return;
192	    try {
193	      const uuid = await anchor.requestPersistentHandle();
194	      if (!this.placed.includes(placed)) {
195	        await this.session?.deletePersistentAnchor?.(uuid);
196	        return;
197	      }
198	      placed.uuid = uuid;
199	      this.save();
200	    } catch (error) {
201	      // Quest には永続アンカーの個数上限がある。超えると失敗するが、このセッション中は使える。
202	      this.persistFailures++;
203	      console.warn('[placement] アンカーを永続化できませんでした', error);
204	    }
205	  }
206	
207	  private add(placed: Placed): void {
208	    this.placed.push(placed);
209	    this.app.scene.add(placed.object);
210	  }
211	}
212	
213	function loadSaved(): Saved[] {
214	  try {
215	    const parsed: unknown = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? '[]');
216	    if (!Array.isArray(parsed)) return [];
217	    return parsed.filter(
218	      (item): item is Saved => typeof item?.uuid === 'string' && typeof item?.kind === 'string' && item.kind in BUILDERS,
219	    );
220	  } catch {
221	    return [];
222	  }
223	}
224	
225	function store(saved: Saved[]): void {
226	  try {
227	    localStorage.setItem(STORAGE_KEY, JSON.stringify(saved));
228	  } catch (error) {
229	    console.warn('[placement] 保存できませんでした', error);
230	  }
231	}
232	
233	function build(kind: Kind): THREE.Group {
234	  const group = BUILDERS[kind]();
235	  group.traverse((object) => {
236	    object.castShadow = true;
237	  });
238	  return group;
239	}
240	
241	function standard(color: number, options: THREE.MeshStandardMaterialParameters = {}): THREE.MeshStandardMaterial {
242	  return new THREE.MeshStandardMaterial({ color, roughness: 0.8, ...options });
243	}
244	
245	function part(geometry: THREE.BufferGeometry, material: THREE.Material, x: number, y: number, z: number): THREE.Mesh {
246	  const mesh = new THREE.Mesh(geometry, material);
247	  mesh.position.set(x, y, z);
248	  return mesh;
249	}
250	
251	/** 物の原点は接地点。水平面用は +Y が上、壁用は +Z が手前。 */
252	const BUILDERS: Record<Kind, () => THREE.Group> = {
253	  plant() {
254	    const leaf = standard(0x3f9b55);
255	    return new THREE.Group().add(
256	      part(new THREE.CylinderGeometry(0.07, 0.05, 0.1, 20), standard(0xb5653b), 0, 0.05, 0),
257	      part(new THREE.SphereGeometry(0.09, 16, 12), leaf, 0, 0.19, 0),
258	      part(new THREE.SphereGeometry(0.07, 16, 12), leaf, 0.05, 0.27, 0.02),
259	      part(new THREE.SphereGeometry(0.06, 16, 12), leaf, -0.04, 0.3, -0.03),
260	    );
261	  },
262	  lamp() {
263	    const metal = standard(0x2f3542, { roughness: 0.4, metalness: 0.6 });
264	    return new THREE.Group().add(
265	      part(new THREE.CylinderGeometry(0.08, 0.09, 0.02, 24), metal, 0, 0.01, 0),
266	      part(new THREE.CylinderGeometry(0.008, 0.008, 0.5, 8), metal, 0, 0.27, 0),
267	      part(
268	        new THREE.SphereGeometry(0.07, 20, 14),
269	        standard(0xfff1c9, { emissive: 0xffc56b, emissiveIntensity: 1.2 }),
270	        0,
271	        0.56,
272	        0,
273	      ),
274	    );
275	  },
276	  tower() {
277	    const group = new THREE.Group();
278	    [0xff6b6b, 0xffd166, 0x4f8cff].forEach((color, i) => {
279	      const size = 0.12 - i * 0.025;
280	      const block = part(new THREE.BoxGeometry(size, 0.08, size), standard(color), 0, 0.04 + i * 0.08, 0);
281	      block.rotation.y = i * 0.5;
282	      group.add(block);
283	    });
284	    return group;
285	  },
286	  picture() {
287	    const canvas = document.createElement('canvas');
288	    canvas.width = 256;
289	    canvas.height = 192;
290	    const g = canvas.getContext('2d')!;
291	    const hue = Math.floor(Math.random() * 360);
292	    const sky = g.createLinearGradient(0, 0, 0, canvas.height);
293	    sky.addColorStop(0, `hsl(${hue}, 70%, 30%)`);
294	    sky.addColorStop(1, `hsl(${(hue + 60) % 360}, 80%, 70%)`);
295	    g.fillStyle = sky;
296	    g.fillRect(0, 0, canvas.width, canvas.height);
297	    g.fillStyle = `hsl(${(hue + 180) % 360}, 80%, 75%)`;
298	    g.beginPath();
299	    g.arc(180, 70, 28, 0, Math.PI * 2);
300	    g.fill();
301	    const texture = new THREE.CanvasTexture(canvas);
302	    texture.colorSpace = THREE.SRGBColorSpace;
303	    return new THREE.Group().add(
304	      part(new THREE.BoxGeometry(0.44, 0.34, 0.02), standard(0x3b2a1e), 0, 0, 0.01),
305	      part(new THREE.PlaneGeometry(0.4, 0.3), new THREE.MeshBasicMaterial({ map: texture }), 0, 0, 0.021),
306	    );
307	  },
308	};
