5	
6	const WIDTH = 0.64;
7	const PIXELS_PER_METER = 1250;
8	const ROW_HEIGHT = 58;
9	const HEADER_HEIGHT = 84;
10	const FOOTER_HEIGHT = 56;
11	const REDRAW_INTERVAL = 0.5;
12	/** パネルを出す位置の、頭からの距離 (m) */
13	const DISTANCE = 1.1;
14	
15	const _forward = new THREE.Vector3();
16	
17	/**
18	 * 各 WebXR 機能が有効になったかと、いま何が取れているかを空間内に表示する。
19	 * optionalFeatures で要求した機能が実際に使えるかは、session.enabledFeatures で分かる。
20	 */
21	export class StatusPanel implements Feature {
22	  readonly name = 'status';
23	  visible = true;
24	
25	  private readonly panel: CanvasPanel;
26	  /** 機能 id → 現在の状況を 1 行で返す関数 */
27	  private readonly details = new Map<string, () => string>();
28	  private footer: () => string = () => '';
29	  private enabledFeatures: readonly string[] | undefined;
30	  private needsPlacement = true;
31	  private lastDraw = -Infinity;
32	  private frames = 0;
33	  private fps = 0;
34	
35	  constructor(app: App) {
36	    const height = (HEADER_HEIGHT + ALL_FEATURES.length * ROW_HEIGHT + FOOTER_HEIGHT) / PIXELS_PER_METER;
37	    this.panel = new CanvasPanel(WIDTH, height, PIXELS_PER_METER);
38	    this.panel.mesh.visible = false;
39	    app.scene.add(this.panel.mesh);
40	    app.menu.addToggle(
41	      '状態パネル',
42	      () => this.visible,
43	      (value) => {
44	        this.visible = value;
45	        // 出し直したときは、いま向いている方に置く。
46	        this.needsPlacement = value;
47	      },
48	    );
49	  }
50	
51	  setDetail(featureId: string, detail: () => string): void {
52	    this.details.set(featureId, detail);
53	  }
54	
55	  setFooter(footer: () => string): void {
56	    this.footer = footer;
57	  }
58	
59	  start(session: XRSession): void {
60	    this.enabledFeatures = session.enabledFeatures;
61	    this.needsPlacement = true;
62	    this.lastDraw = -Infinity;
63	  }
64	
65	  end(): void {
66	    this.panel.mesh.visible = false;
67	  }
68	
69	  update(ctx: FrameContext): void {
70	    const mesh = this.panel.mesh;
71	    mesh.visible = this.visible;
72	    this.frames++;
73	    if (!this.visible) return;
74	
75	    if (this.needsPlacement) {
76	      this.needsPlacement = false;
77	      _forward.set(0, 0, -1).applyQuaternion(ctx.headQuaternion).setY(0).normalize();
78	      mesh.position.copy(ctx.headPosition).addScaledVector(_forward, DISTANCE);
79	      mesh.lookAt(ctx.headPosition);
80	    }
81	    const elapsed = ctx.time - this.lastDraw;
82	    if (elapsed < REDRAW_INTERVAL) return;
83	    this.fps = Number.isFinite(elapsed) ? this.frames / elapsed : 0;
84	    this.frames = 0;
85	    this.lastDraw = ctx.time;
86	    this.draw();
87	  }
88	
89	  private draw(): void {
90	    const g = this.panel.context;
91	    const { width, height } = this.panel.canvas;
92	    g.clearRect(0, 0, width, height);
93	    g.fillStyle = 'rgba(16, 20, 28, 0.85)';
94	    g.beginPath();
95	    g.roundRect(0, 0, width, height, 24);
96	    g.fill();
97	
98	    g.textBaseline = 'middle';
99	    g.textAlign = 'left';
100	    g.fillStyle = '#ffffff';
101	    g.font = 'bold 30px system-ui, sans-serif';
102	    g.fillText('WebXR 機能の状態', 24, HEADER_HEIGHT / 2);
103	    g.textAlign = 'right';
104	    g.fillStyle = '#a9b4c8';
105	    g.font = '22px system-ui, sans-serif';
106	    g.fillText(`${this.fps.toFixed(0)} fps`, width - 24, HEADER_HEIGHT / 2);
107	
108	    ALL_FEATURES.forEach((feature, i) => {
109	      const y = HEADER_HEIGHT + i * ROW_HEIGHT + ROW_HEIGHT / 2;
110	      const enabled = this.enabledFeatures?.includes(feature.id);
111	      g.textAlign = 'left';
112	      g.font = 'bold 24px system-ui, sans-serif';
113	      g.fillStyle = enabled === undefined ? '#a9b4c8' : enabled ? '#6fe09a' : '#ff7b7b';
114	      g.fillText(enabled === undefined ? '不明' : enabled ? '有効' : '非対応', 24, y);
115	      g.fillStyle = '#ffffff';
116	      g.fillText(feature.label, 120, y - 12);
117	      g.fillStyle = '#8a94a8';
118	      g.font = '18px ui-monospace, monospace';
119	      g.fillText(feature.id, 120, y + 14);
120	      g.fillStyle = '#e8ecf4';
121	      g.font = '22px system-ui, sans-serif';
122	      g.fillText(this.details.get(feature.id)?.() ?? '', 380, y, width - 380 - 24);
123	    });
124	
